const crypto = require('crypto');
const base = String($env.ODOO_PROD_ORCH_BASE_URL || '').replace(/\/$/, '');
const secret = String($env.ODOO_ORCH_WEBHOOK_SECRET_PROD || '');
if (!base || !secret) throw new Error('missing_odoo_prod_env');
const appId = Number($input.first().json.application_id);
const idem = String($input.first().json.idempotency_key || '');
const cvFacts = String($input.first().json.cv_facts_json || '{}');
const raw = Buffer.from('');
const ts = Math.floor(Date.now()/1000).toString();
const sig = crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');
return [{
  json: {
    application_id: appId,
    idempotency_key: idem,
    cv_facts_json: cvFacts,
    odoo_base: base,
    get_url: `${base}/linkedin/orchestrator/v1/applications/${appId}`,
    ts,
    signature: `sha256=${sig}`,
    n8n_execution_hint: $execution?.id || 'manual-cli'
  }
}];

const prev = $('Sign GET Payload Request').first().json;
const resp = $input.first().json;
if (!resp.ok || !resp.data) throw new Error('odoo_fetch_failed:' + (resp.code || resp.error || 'unknown'));
const data = resp.data;
if (Number(data.account_id) === 1) throw new Error('company_account_forbidden');
const job = data.job || {};
const profile = data.candidate_profile || {};
// never invent sensitive answers — omit unset
const difyBody = {
  inputs: {
    job_json: JSON.stringify(job),
    candidate_profile_json: JSON.stringify(profile),
    cv_facts_json: prev.cv_facts_json
  },
  response_mode: 'blocking',
  user: 'n8n-job-orch-prod'
};
const difyKey = String($env.DIFY_API_KEY_JOB_PACK_PROD || '').trim();
let difyBase = String($env.DIFY_BASE_URL || '').trim().replace(/\/$/, '');
if (difyBase && !difyBase.endsWith('/v1')) difyBase += '/v1';
if (!difyKey || !difyBase) throw new Error('missing_dify_prod_env');
return [{
  json: {
    application_id: prev.application_id,
    idempotency_key: prev.idempotency_key,
    odoo_base: prev.odoo_base,
    account_id: data.account_id,
    apply_platform: job.apply_platform,
    dify_url: difyBase + '/workflows/run',
    dify_key: difyKey,
    dify_body: difyBody,
    policy: data.policy || {}
  }
}];

const crypto = require('crypto');
const ctx = $('Prepare Dify Inputs').first().json;
const resp = $input.first().json;
const required = ['match_decision','exclusion_flags','selected_cv','cover_letter','screening_qa','missing_facts','risk_notes','recommended_channel'];
const sensitive = ['salary_expectation','notice_period','visa_sponsorship','uae_relocation'];
const matchOk = new Set(['shortlist','reject','needs_human']);
const channelOk = new Set(['browser_dry_run','manual_linkedin','email','manual_browser','skip']);

if (resp.code || resp.status === 'failed' || (resp.data && resp.data.status === 'failed')) {
  throw new Error('dify_failed:' + ((resp.data && resp.data.error) || resp.message || 'unknown'));
}
const outputs = (resp.data && resp.data.outputs) || resp.outputs || {};
let pack = outputs.pack_json || outputs.text || outputs;
if (typeof pack === 'string') {
  try { pack = JSON.parse(pack); }
  catch (e) {
    const s = pack.indexOf('{'); const e2 = pack.lastIndexOf('}');
    if (s < 0) throw new Error('pack_not_json');
    pack = JSON.parse(pack.slice(s, e2+1));
  }
}
if (!pack || typeof pack !== 'object') throw new Error('pack_not_object');
if (pack.invented_facts) throw new Error('invented_facts_forbidden');
for (const k of required) if (!(k in pack)) throw new Error('missing_'+k);
if (!matchOk.has(pack.match_decision)) throw new Error('bad_match_decision');
if (!channelOk.has(pack.recommended_channel)) throw new Error('bad_recommended_channel');
if (!Array.isArray(pack.missing_facts)) throw new Error('missing_facts_not_list');
if (!Array.isArray(pack.screening_qa)) throw new Error('screening_qa_not_list');

// Fail-closed enrichment: ensure unset sensitive fields are listed
const missing = new Set(pack.missing_facts.map(String));
for (const f of sensitive) missing.add(f); // profile sanitized omitted them in UAT
pack.missing_facts = Array.from(missing);

// LinkedIn hard route
if (String(ctx.apply_platform) === 'linkedin') {
  pack.recommended_channel = 'manual_linkedin';
} else if (pack.recommended_channel === 'skip' && ['bebee','greenhouse','lever','company_ats','aggregator'].includes(String(ctx.apply_platform))) {
  pack.recommended_channel = 'browser_dry_run';
}

const difyRunId = resp.workflow_run_id || (resp.data && resp.data.id) || '';
const secret = String($env.ODOO_ORCH_WEBHOOK_SECRET_PROD || '');
const packBodyObj = {
  pack,
  n8n_execution_id: String($execution?.id || 'manual-cli'),
  dify_run_id: String(difyRunId)
};
const raw = Buffer.from(JSON.stringify(packBodyObj));
const ts = Math.floor(Date.now()/1000).toString();
const sig = crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');

return [{
  json: {
    application_id: ctx.application_id,
    idempotency_key: ctx.idempotency_key,
    odoo_base: ctx.odoo_base,
    apply_platform: ctx.apply_platform,
    pack,
    dify_run_id: String(difyRunId),
    pack_url: `${ctx.odoo_base}/linkedin/orchestrator/v1/applications/${ctx.application_id}/pack`,
    pack_body: packBodyObj,
    pack_raw: raw.toString(),
    ts,
    signature: `sha256=${sig}`,
    worker_url: String($env.JOB_APPLY_WORKER_URL || 'http://uat-job-worker:8095').replace(/\/$/, '')
  }
}];

const crypto = require('crypto');
const ctx = $('Validate Pack JSON Fail-Closed').first().json;
const packWrite = $('Write Pack to Odoo Production').first().json;
const worker = $input.first().json;
if (!packWrite.ok) throw new Error('pack_write_failed:' + (packWrite.code || packWrite.error || 'unknown'));
if (worker.stop_reason === 'linkedin_blocked') throw new Error('unexpected_linkedin');
const state = worker.state === 'drafted' ? 'drafted' : (worker.state === 'stopped' ? 'stopped' : 'failed');
const attemptBody = {
  idempotency_key: ctx.idempotency_key,
  dry_run: true,
  state,
  stop_reason: worker.stop_reason || 'none',
  stop_detail: String(worker.message || '').slice(0, 500),
  final_url: worker.final_url || 'fixture://bebee_like.html',
  worker_attempt_id: worker.attempt_id || '',
  n8n_execution_id: String($execution?.id || 'manual-cli'),
  dify_run_id: ctx.dify_run_id,
  response: {
    sanitized: true,
    state: worker.state,
    stop_reason: worker.stop_reason,
    adapter_used: worker.adapter_used,
    filled_fields: worker.filled_fields || [],
    screenshot_count: (worker.screenshot_paths || []).length
  }
};
const secret = String($env.ODOO_ORCH_WEBHOOK_SECRET_PROD || '');
const raw = Buffer.from(JSON.stringify(attemptBody));
const ts = Math.floor(Date.now()/1000).toString();
const sig = crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');
return [{
  json: {
    application_id: ctx.application_id,
    idempotency_key: ctx.idempotency_key,
    dify_run_id: ctx.dify_run_id,
    worker_attempt_id: worker.attempt_id,
    attempt_url: `${ctx.odoo_base}/linkedin/orchestrator/v1/applications/${ctx.application_id}/attempts`,
    attempt_body: attemptBody,
    ts,
    signature: `sha256=${sig}`,
    worker_state: worker.state,
    worker_stop_reason: worker.stop_reason
  }
}];

const prep = $('Prepare Attempt Write').first().json;
const att = $input.first().json;
if (!att.ok) throw new Error('attempt_write_failed:' + (att.code || att.error || 'unknown'));
return [{
  json: {
    ok: true,
    application_id: prep.application_id,
    attempt_id: att.attempt_id,
    attempt_state: att.state,
    idempotent: !!att.idempotent,
    idempotency_key: prep.idempotency_key,
    dify_run_id: prep.dify_run_id,
    worker_attempt_id: prep.worker_attempt_id,
    worker_state: prep.worker_state,
    worker_stop_reason: prep.worker_stop_reason,
    n8n_execution_id: String($execution?.id || 'manual-cli')
  }
}];
